import { readFile, writeFile } from 'node:fs/promises';

const root = new URL('../', import.meta.url);
const license = await readFile(new URL('node_modules/prismjs/LICENSE', root), 'utf8');
let output =
  '// Generated by npm run editor. Prism 1.30.0 core + clike + JavaScript.\n/*!\n' +
  license +
  '\n*/\n';
output += 'globalThis.Prism = { manual: true, disableWorkerMessageHandler: true };\n';
for (const name of ['core', 'clike', 'javascript'])
  output +=
    (await readFile(new URL(`node_modules/prismjs/components/prism-${name}.js`, root), 'utf8')) +
    '\n';
output +=
  'export function highlightJavaScript(source) { return Prism.highlight(source, Prism.languages.javascript, "javascript"); }\n';
const target = new URL('src/editor-highlighter.js', root);
if (process.argv.includes('--check')) {
  if ((await readFile(target, 'utf8')) !== output)
    throw new Error('Editor highlighter is stale; run npm run editor');
} else await writeFile(target, output);
